import fs from 'node:fs';
const repo=process.env.GITHUB_REPOSITORY;
if(repo!=='mattheube/MyProjects')throw Error('Unexpected repository');
const headers={Authorization:'Bearer '+process.env.GH_TOKEN,Accept:'application/vnd.github+json','X-GitHub-Api-Version':'2022-11-28','User-Agent':'MyProjects-release-import'};
async function api(path,method='GET',body){const r=await fetch('https://api.github.com/repos/'+repo+path,{method,headers,body:body===undefined?undefined:JSON.stringify(body)});if(r.status===404)return null;if(!r.ok)throw Error(method+' '+path+' '+r.status+' '+await r.text());return r.status===204?null:r.json();}
const meta=JSON.parse(fs.readFileSync('.github/import-beta15.json','utf8'));
let release=await api('/releases/tags/'+meta.tag);if(!release)release=await api('/releases','POST',{tag_name:meta.tag,target_commitish:'main',name:meta.name,body:meta.body,draft:true,prerelease:true,make_latest:'false'});
const small={"manifest":"","checksums":"","soundpacks":"eyJzY2hlbWFWZXJzaW9uIjoxLCJwYWNrcyI6W119DQo="};
for(const [key,value] of Object.entries(small)){const name=key==='checksums'?'checksums.txt':key+'.json';const found=release.assets.find(a=>a.name===name);if(found)continue;const r=await fetch(release.upload_url.split('{')[0]+'?name='+name,{method:'POST',headers:{...headers,'Content-Type':'application/octet-stream'},body:Buffer.from(value,'base64')});if(!r.ok)throw Error('Upload '+name+' '+r.status);}
console.log('Prepared draft '+meta.tag+'; waiting for its two verified binary files.');
for(let attempt=0;attempt<90;attempt++){release=await api('/releases/'+release.id);if(meta.assets.every(a=>release.assets.some(b=>a.name===b.name&&a.size===b.size&&a.digest===b.digest))){if(release.draft)release=await api('/releases/'+release.id,'PATCH',{draft:false,prerelease:true,make_latest:'false'});console.log('Published '+meta.tag+' with all five verified assets.');process.exit(0);}await new Promise(r=>setTimeout(r,10000));}
throw Error('Draft remains private to repository maintainers: waiting for binary uploads.');
